// Some portions generated by Co-Pilot
"use client";

import { useRouter, useSearchParams, usePathname } from "next/navigation";
import { useTransition } from "react";
import { useTranslations } from "next-intl";
import { FilterSelect, SelectOption } from "./FilterSelect";

interface NewsFiltersProps {
  tags: SelectOption[];
  authors: SelectOption[];
}

type FilterKey = "source" | "tag" | "author";

export default function NewsFilters({ tags, authors }: NewsFiltersProps) {
  const t = useTranslations("ModernPages.news");
  const router = useRouter();
  const searchParams = useSearchParams();
  const pathname = usePathname();
  const [isPending, startTransition] = useTransition();

  const selectedTags = (searchParams.get("tag") || "")
    .split(",")
    .map((t) => t.trim())
    .filter(Boolean);

  const addTag = (value: string) => {
    const params = new URLSearchParams(searchParams.toString());

    const currentTags = selectedTags.includes(value)
      ? selectedTags
      : [...selectedTags, value];

    params.set("tag", currentTags.join(","));
    params.delete("page");

    const newQuery = params.toString();
    const cleanPath = pathname.replace(/\/page\/\d+$/, "");

    startTransition(() => {
      router.replace(`${cleanPath}${newQuery ? `?${newQuery}` : ""}`);
    });
  };

  const removeTag = (tagToRemove: string) => {
    const params = new URLSearchParams(searchParams.toString());

    const updatedTags = selectedTags.filter((t) => t !== tagToRemove);

    if (updatedTags.length > 0) {
      params.set("tag", updatedTags.join(","));
    } else {
      params.delete("tag");
    }

    params.delete("page");

    const newQuery = params.toString();
    const cleanPath = pathname.replace(/\/page\/\d+$/, "");

    startTransition(() => {
      router.replace(`${cleanPath}${newQuery ? `?${newQuery}` : ""}`);
    });
  };

  const handleChange = (key: FilterKey, value: string) => {
    const params = new URLSearchParams(searchParams.toString());
    if (searchParams.get(key) === value) return;

    if (value) {
      params.set(key, value);
    } else {
      params.delete(key);
    }

    params.delete("page");

    const newQuery = params.toString();
    const cleanPath = pathname.replace(/\/page\/\d+$/, "");

    startTransition(() => {
      router.replace(`${cleanPath}${newQuery ? `?${newQuery}` : ""}`);
    });
  };
  const sourceOptions: SelectOption[] = [
    { value: "adoptium", label: "Adoptium" },
    { value: "eclipse", label: "Eclipse" },
  ];

  return (
    <section
      className="mx-auto max-w-7xl px-6 pt-8 sm:px-8"
      aria-labelledby="news-filters-title"
      aria-busy={isPending}
    >
      <div className="rounded-2xl border border-white/10 bg-white/[0.025] p-5">
        <h2 id="news-filters-title" className="mb-4 text-base font-semibold">
          {t("filters")}
        </h2>
        <div className="flex w-full flex-col gap-3 sm:flex-row">
          <div className="sm:flex-1 sm:min-w-0">
            <FilterSelect
              label={t("sources")}
              value={searchParams.get("source") || ""}
              options={sourceOptions}
              onChange={(value) => handleChange("source", value)}
              disabled={isPending}
            />
          </div>

          <div className="sm:flex-1 sm:min-w-0">
            <FilterSelect
              label={t("tags")}
              value={searchParams.get("tag") || ""}
              options={tags}
              onChange={(value) =>
                value ? addTag(value) : handleChange("tag", "")
              }
              disabled={isPending}
            />
          </div>

          <div className="sm:flex-1 sm:min-w-0">
            <FilterSelect
              label={t("authors")}
              value={searchParams.get("author") || ""}
              options={authors}
              onChange={(value) => handleChange("author", value)}
              disabled={isPending}
            />
          </div>
        </div>
        {selectedTags.length > 0 && (
          <div className="flex flex-wrap gap-2 mt-4 max-w-4xl">
            {selectedTags.map((tag) => (
              <div
                key={tag}
                className="flex items-center gap-2 px-3 py-1 text-sm bg-purple-700 text-white rounded-full"
              >
                {tag}
                <button
                  onClick={() => removeTag(tag)}
                  aria-label={t("remove-tag", { tag })}
                  className="text-xs hover:text-gray-200 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-pink"
                >
                  ×
                </button>
              </div>
            ))}
          </div>
        )}
      </div>
    </section>
  );
}
